// Articulated 32px visitors: soft silhouettes, bright eyes and warm garden colours.
const ink='#293b2a',cream='#fff0c7',gold='#efc45d',ochre='#ad773c',pale='#e4efd9',blush='#e6a186';
const path=(d,fill)=>`<path d="${d}" fill="${fill}"/>`;
const eye=(x,y)=>`<path d="M${x} ${y}h3v4h-3z" fill="${ink}"/><rect x="${x}" y="${y}" width="1" height="1" fill="#fff9e4"/>`;
const face=(x,y)=>`<g class="sprite-eyes">${eye(x,y)}${eye(x+6,y)}</g>${path(`M${x-1} ${y+4}h2v1h-2zm9 0h2v1h-2z`,blush)}${path(`M${x+3} ${y+4}h1v1h1v-1h1v2h-3z`,ink)}`;
const feet=`<g class="sprite-feet">${path('M9 22h2v4H8v-1h1zm7 0h2v5h-3v-1h1zm7-1h2v4h-3v-1h1z',ochre)}</g>`;
function moth(){return `<g class="moth-wing wing-left">${path('M14 13L10 7H5L2 10V15L5 18L3 21L5 25H9L14 21Z',ink)}${path('M13 14L9 9H5L4 11V14L8 18L5 21L6 23H9L13 20Z','#d4aa6d')}${path('M10 13L7 10H5V13L8 16H11ZM10 20H6V22H9Z',cream)}${path('M6 12H8V14H6ZM7 20H9V22H7Z',gold)}</g><g class="moth-wing wing-right">${path('M18 13L22 7H27L30 10V15L27 18L29 21L27 25H23L18 21Z',ink)}${path('M19 14L23 9H27L28 11V14L24 18L27 21L26 23H23L19 20Z','#d4aa6d')}${path('M22 13L25 10H27V13L24 16H21ZM22 20H26V22H23Z',cream)}${path('M24 12H26V14H24ZM23 20H25V22H23Z',gold)}</g>${path('M12 14H21V22H20V25H18V27H15V25H13V22H12Z',ink)}${path('M14 16H19V23H18V25H16V23H14Z',gold)}${path('M11 12H12V10H15V9H18V10H21V12H22V18H21V20H12V18H11Z',ink)}${path('M12 13H13V11H15V10H18V11H20V13H21V18H19V19H14V18H12Z',cream)}<g class="sprite-eyes">${eye(12,13)}${eye(18,13)}</g>${path('M12 17H14V18H12ZM19 17H21V18H19Z',blush)}${path('M15 17H16V18H17V17H18V19H15Z',ochre)}<g class="sprite-antennae">${path('M13 11V8H11V6H13V7H14V10ZM19 11V8H21V6H19V7H18V10Z',ochre)}</g>`;}
function striped(wasp){return `<g class="flight-wings">${path(wasp?'M18 14L8 4H4L3 6L5 9L14 16Z':'M18 14L12 4H7L5 6V9L12 16Z',ink)}${path(wasp?'M17 13L8 5H5V7L14 14Z':'M16 13L11 5H8L7 7V9L13 14Z',pale)}${path('M18 14L14 8H11V11L15 16H19Z','#bcd4bd')}${path('M9 6H11V8H9Z',cream)}</g>${feet}${path(wasp?'M4 18L10 13H20V23H11L4 24Z':'M4 16H5V14H8V12H17V13H20V16H23V22H21V25H17V26H8V25H5V23H4Z',ink)}${path(wasp?'M6 18L11 15H19V21H11L6 22Z':'M6 16H8V14H17V15H19V18H21V21H19V23H16V24H9V23H7V21H6Z',gold)}${path(wasp?'M9 16H12V22H9ZM16 15H18V22H16Z':'M10 14H13V24H10ZM17 15H19V23H17Z',ochre)}${path('M7 16H9V18H7ZM14 14H16V15H14Z',cream)}${path('M20 12H27V13H29V15H31V23H29V25H22V24H20V22H19V15H20Z',ink)}${path('M21 14H23V13H27V14H29V16H30V22H28V24H23V23H21V21H20V16H21Z',wasp?'#f0ce6c':'#f8d77c')}${face(21,16)}<g class="sprite-antennae">${path('M23 14V10H21V8H23V9H24V13ZM28 14V10H30V8H28V9H27V13Z',ochre)}</g>`;}
function ladybird(){return `${feet}${path('M4 13H5V10H8V8H12V7H18V8H21V10H24V14H25V22H23V25H19V27H10V26H7V24H4Z',ink)}${path('M6 14H7V11H10V9H17V10H20V12H22V15H23V21H21V24H18V25H11V24H8V22H6Z','#dc6545')}${path('M8 12H11V10H17V11H20V14H8Z','#f08b61')}${path('M15 9H17V25H15ZM9 14H12V17H9ZM18 17H21V20H18ZM8 21H11V23H8Z',ink)}${path('M11 10H13V12H11Z',cream)}${path('M21 15H28V16H30V18H31V24H29V26H23V25H21V23H20V18H21Z',ink)}${path('M22 17H24V16H28V18H30V23H28V25H24V24H22Z','#69744e')}${face(22,18)}<g class="sprite-antennae">${path('M24 17V13H22V12H24V14H25V17ZM28 17V14H30V12H29V13H27V17Z',ochre)}</g>`;}
function caterpillar(){return `${feet}<g class="crawler-body">${path('M2 18H3V15H6V13H10V14H12V12H16V13H19V15H23V24H6V23H3V21H2Z',ink)}${path('M4 18H5V16H7V15H10V22H7V21H5V20H4ZM11 17H13V14H16V15H18V23H13V22H11ZM19 17H23V22H19Z','#93b957')}${path('M6 15H9V18H6ZM13 14H16V17H13ZM20 17H23V19H20Z','#cddd87')}</g>${path('M21 12H28V13H30V15H31V23H29V25H22V24H20V22H19V16H20V14H21Z',ink)}${path('M22 14H24V13H28V15H30V22H28V24H23V23H21V21H20V17H21V15H22Z','#b7cf75')}${face(21,16)}<g class="sprite-antennae">${path('M23 14V10H21V8H23V9H24V14ZM28 14V10H30V8H28V9H27V14Z',ochre)}${path('M21 8H23V10H21ZM28 8H30V10H28Z',gold)}</g>`;}
export function visitorArt(type){const draw={moth,bee:()=>striped(false),wasp:()=>striped(true),ladybird,caterpillar}[type];return draw?`<svg class="live-sprite" viewBox="0 0 32 32" aria-hidden="true" shape-rendering="crispEdges">${draw()}</svg>`:'';}
